codeExamples.code:
{% snapshot orders_snapshot %}

{{
    config(
        target_schema='snapshots',
        unique_key='order_id',
        strategy='timestamp',
        updated_at='updated_at',
        invalidate_hard_deletes=true
    )
}}

select
    order_id,
    customer_id,
    status,
    amount_cents,
    updated_at
from {{ source('shop', 'orders') }}

{% endsnapshot %}

{% snapshot customers_snapshot %}

{{
    config(
        target_schema='snapshots',
        unique_key='customer_id',
        strategy='check',
        check_cols=['status', 'tier', 'address']
    )
}}

select
    customer_id,
    status,
    tier,
    address,
    email
from {{ source('crm', 'customers') }}

{% endsnapshot %}
